//! Polygon triangulation library: a faithful Rust port of the mapbox `earcut`
//! algorithm (ear clipping with z-order hashing for large inputs), implemented
//! from scratch using only `std`.
//!
//! Polygons are `&[Vec<[f64; 2]>]` — a list of rings, the first being the
//! outer ring and the rest holes. The result is a list of vertex indices
//! (flattened across all rings) forming triangles.

pub type Index = u32;

/// A vertex of the polygon stored in a doubly linked list (plus an optional
/// second linked list used for z-order hashing).
struct Node {
    i: Index,
    x: f64,
    y: f64,
    prev: usize,
    next: usize,
    z: i32,
    prev_z: Option<usize>,
    next_z: Option<usize>,
    steiner: bool,
}

impl Node {
    fn new(i: Index, x: f64, y: f64, id: usize) -> Self {
        Node {
            i,
            x,
            y,
            prev: id,
            next: id,
            z: 0,
            prev_z: None,
            next_z: None,
            steiner: false,
        }
    }
}

pub struct Earcut {
    nodes: Vec<Node>,
    pub indices: Vec<Index>,
    vertices: usize,
    hashing: bool,
    min_x: f64,
    max_x: f64,
    min_y: f64,
    max_y: f64,
    inv_size: f64,
}

impl Default for Earcut {
    fn default() -> Self {
        Self::new()
    }
}

impl Earcut {
    pub fn new() -> Self {
        Earcut {
            nodes: Vec::new(),
            indices: Vec::new(),
            vertices: 0,
            hashing: false,
            min_x: 0.0,
            max_x: 0.0,
            min_y: 0.0,
            max_y: 0.0,
            inv_size: 0.0,
        }
    }

    pub fn run(&mut self, points: &[Vec<[f64; 2]>]) {
        // reset
        self.indices.clear();
        self.vertices = 0;

        if points.is_empty() {
            return;
        }

        let mut threshold: i64 = 80;
        let mut i = 0;
        while threshold >= 0 && i < points.len() {
            threshold -= points[i].len() as i64;
            i += 1;
        }

        // outer node
        let outer_node = match self.linked_list(&points[0], true) {
            Some(n) => n,
            None => return,
        };
        if self.nodes[outer_node].prev == self.nodes[outer_node].next {
            return;
        }

        let mut outer_node = outer_node;
        if points.len() > 1 {
            outer_node = self.eliminate_holes(points, outer_node);
        }

        // if the shape is not too simple, we'll use z-order curve hash later;
        // calculate polygon bbox
        self.hashing = threshold < 0;
        if self.hashing {
            let mut p = self.nodes[outer_node].next;
            self.min_x = self.nodes[outer_node].x;
            self.max_x = self.nodes[outer_node].x;
            self.min_y = self.nodes[outer_node].y;
            self.max_y = self.nodes[outer_node].y;
            loop {
                let x = self.nodes[p].x;
                let y = self.nodes[p].y;
                if x < self.min_x {
                    self.min_x = x;
                }
                if y < self.min_y {
                    self.min_y = y;
                }
                if x > self.max_x {
                    self.max_x = x;
                }
                if y > self.max_y {
                    self.max_y = y;
                }
                p = self.nodes[p].next;
                if p == outer_node {
                    break;
                }
            }

            // min_x, min_y and inv_size are later used to transform coords
            // into integers for z-order calculation
            self.inv_size = (self.max_x - self.min_x).max(self.max_y - self.min_y);
            self.inv_size = if self.inv_size != 0.0 {
                32767.0 / self.inv_size
            } else {
                0.0
            };
        }

        self.earcut_linked(outer_node, 0);
    }

    /// Create a circular doubly linked list from polygon points in the
    /// specified winding order.
    fn linked_list(&mut self, points: &[[f64; 2]], clockwise: bool) -> Option<usize> {
        let mut sum = 0.0f64;
        let len = points.len();
        let mut last: Option<usize> = None;

        // calculate original winding order of a polygon ring
        let mut i = 0;
        let mut j = if len > 0 { len - 1 } else { 0 };
        while i < len {
            let p1 = points[i];
            let p2 = points[j];
            sum += (p2[0] - p1[0]) * (p1[1] + p2[1]);
            j = i;
            i += 1;
        }

        // link points into circular doubly-linked list in the specified
        // winding order
        if clockwise == (sum > 0.0) {
            for i in 0..len {
                last = Some(self.insert_node(self.vertices + i, points[i], last));
            }
        } else {
            let mut i = len;
            while i > 0 {
                i -= 1;
                last = Some(self.insert_node(self.vertices + i, points[i], last));
            }
        }

        if let Some(l) = last {
            let next = self.nodes[l].next;
            if self.equals(l, next) {
                self.remove_node(l);
                last = Some(next);
            }
        }

        self.vertices += len;
        last
    }

    /// Eliminate colinear or duplicate points.
    fn filter_points(&mut self, start: usize, end: Option<usize>) -> usize {
        let mut end = end.unwrap_or(start);
        let mut p = start;
        loop {
            let mut again = false;
            let p_next = self.nodes[p].next;
            let p_prev = self.nodes[p].prev;

            if !self.nodes[p].steiner
                && (self.equals(p, p_next) || self.area(p_prev, p, p_next) == 0.0)
            {
                self.remove_node(p);
                p = p_prev;
                end = p_prev;

                if p == self.nodes[p].next {
                    break;
                }
                again = true;
            } else {
                p = p_next;
            }

            if !(again || p != end) {
                break;
            }
        }
        end
    }

    /// Main ear slicing loop which triangulates a polygon (given as a linked
    /// list).
    fn earcut_linked(&mut self, ear: usize, pass: i32) {
        let mut ear = ear;

        // interlink polygon nodes in z-order
        if pass == 0 && self.hashing {
            self.index_curve(ear);
        }

        let mut stop = ear;

        // iterate through ears, slicing them one by one
        while self.nodes[ear].prev != self.nodes[ear].next {
            let prev = self.nodes[ear].prev;
            let next = self.nodes[ear].next;

            let is_ear = if self.hashing {
                self.is_ear_hashed(ear)
            } else {
                self.is_ear(ear)
            };

            if is_ear {
                // cut off the triangle
                self.indices.push(self.nodes[prev].i);
                self.indices.push(self.nodes[ear].i);
                self.indices.push(self.nodes[next].i);

                self.remove_node(ear);

                // skipping the next vertex leads to less sliver triangles
                ear = self.nodes[next].next;
                stop = ear;

                continue;
            }

            ear = next;

            // if we looped through the whole remaining polygon and can't find
            // any more ears
            if ear == stop {
                if pass == 0 {
                    // try filtering points and slicing again
                    let e = self.filter_points(ear, None);
                    self.earcut_linked(e, 1);
                } else if pass == 1 {
                    // if this didn't work, try curing all small
                    // self-intersections locally
                    let e = self.filter_points(ear, None);
                    let e = self.cure_local_intersections(e);
                    self.earcut_linked(e, 2);
                } else if pass == 2 {
                    // as a last resort, try splitting the remaining polygon
                    // into two
                    self.split_earcut(ear);
                }
                break;
            }
        }
    }

    /// Check whether a polygon node forms a valid ear with adjacent nodes.
    fn is_ear(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);

        // now make sure we don't have other points inside the potential ear
        let mut p = self.nodes[self.nodes[ear].next].next;

        while p != self.nodes[ear].prev {
            if point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[p].x, self.nodes[p].y)
                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].next;
        }

        true
    }

    fn is_ear_hashed(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);

        // triangle bbox; min & max are calculated like this for speed
        let min_tx = ax.min(bx).min(cx);
        let min_ty = ay.min(by).min(cy);
        let max_tx = ax.max(bx).max(cx);
        let max_ty = ay.max(by).max(cy);

        // z-order range for the current triangle bbox
        let min_z = self.z_order(min_tx, min_ty);
        let max_z = self.z_order(max_tx, max_ty);

        // first look for points inside the triangle in increasing z-order
        let mut p = self.nodes[ear].next_z;
        while let Some(pi) = p {
            if self.nodes[pi].z > max_z {
                break;
            }
            if pi != self.nodes[ear].prev
                && pi != self.nodes[ear].next
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[pi].x, self.nodes[pi].y)
                && self.area(self.nodes[pi].prev, pi, self.nodes[pi].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[pi].next_z;
        }

        // then look for points in decreasing z-order
        p = self.nodes[ear].prev_z;
        while let Some(pi) = p {
            if self.nodes[pi].z < min_z {
                break;
            }
            if pi != self.nodes[ear].prev
                && pi != self.nodes[ear].next
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[pi].x, self.nodes[pi].y)
                && self.area(self.nodes[pi].prev, pi, self.nodes[pi].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[pi].prev_z;
        }

        true
    }

    /// Go through all polygon nodes and cure small local self-intersections.
    fn cure_local_intersections(&mut self, start: usize) -> usize {
        let mut start = start;
        let mut p = start;
        loop {
            let a = self.nodes[p].prev;
            let b = self.nodes[self.nodes[p].next].next;

            // a self-intersection where edge (v[i-1],v[i]) intersects
            // (v[i+1],v[i+2])
            if !self.equals(a, b)
                && self.intersects(a, p, self.nodes[p].next, b)
                && self.locally_inside(a, b)
                && self.locally_inside(b, a)
            {
                self.indices.push(self.nodes[a].i);
                self.indices.push(self.nodes[p].i);
                self.indices.push(self.nodes[b].i);

                // remove two nodes involved
                let p_next = self.nodes[p].next;
                self.remove_node(p);
                self.remove_node(p_next);

                p = b;
                start = b;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        self.filter_points(p, None)
    }

    /// Try splitting polygon into two and triangulate them independently.
    fn split_earcut(&mut self, start: usize) {
        // look for a valid diagonal that divides the polygon into two
        let mut a = start;
        loop {
            let mut b = self.nodes[self.nodes[a].next].next;
            while b != self.nodes[a].prev {
                if self.nodes[a].i != self.nodes[b].i && self.is_valid_diagonal(a, b) {
                    // split the polygon in two by the diagonal
                    let c = self.split_polygon(a, b);

                    // filter colinear points around the cuts
                    let a_next = self.nodes[a].next;
                    let a = self.filter_points(a, Some(a_next));
                    let c_next = self.nodes[c].next;
                    let c = self.filter_points(c, Some(c_next));

                    // run earcut on each half
                    self.earcut_linked(a, 0);
                    self.earcut_linked(c, 0);
                    return;
                }
                b = self.nodes[b].next;
            }
            a = self.nodes[a].next;
            if a == start {
                break;
            }
        }
    }

    /// Link every hole into the outer loop, producing a single-ring polygon
    /// without holes.
    fn eliminate_holes(&mut self, points: &[Vec<[f64; 2]>], mut outer_node: usize) -> usize {
        let len = points.len();

        let mut queue = Vec::new();
        for i in 1..len {
            if let Some(list) = self.linked_list(&points[i], false) {
                if list == self.nodes[list].next {
                    self.nodes[list].steiner = true;
                }
                queue.push(self.get_leftmost(list));
            }
        }
        queue.sort_by(|&a, &b| {
            let (xa, xb) = (self.nodes[a].x, self.nodes[b].x);
            if xa < xb {
                std::cmp::Ordering::Less
            } else if xb < xa {
                std::cmp::Ordering::Greater
            } else {
                std::cmp::Ordering::Equal
            }
        });

        // process holes from left to right
        for q in queue {
            outer_node = self.eliminate_hole(q, outer_node);
        }

        outer_node
    }

    /// Find a bridge between vertices that connects hole with an outer ring
    /// and link it.
    fn eliminate_hole(&mut self, hole: usize, outer_node: usize) -> usize {
        let bridge = match self.find_hole_bridge(hole, outer_node) {
            Some(b) => b,
            None => return outer_node,
        };

        let bridge_reverse = self.split_polygon(bridge, hole);

        // filter collinear points around the cuts
        let br_next = self.nodes[bridge_reverse].next;
        self.filter_points(bridge_reverse, Some(br_next));

        // Check if input node was removed by the filtering
        let b_next = self.nodes[bridge].next;
        self.filter_points(bridge, Some(b_next))
    }

    /// David Eberly's algorithm for finding a bridge between hole and outer
    /// polygon.
    fn find_hole_bridge(&self, hole: usize, outer_node: usize) -> Option<usize> {
        let mut p = outer_node;
        let hx = self.nodes[hole].x;
        let hy = self.nodes[hole].y;
        let mut qx = f64::NEG_INFINITY;
        let mut m: Option<usize> = None;

        // find a segment intersected by a ray from the hole's leftmost point
        // to the left; segment's endpoint with lesser x will be potential
        // connection point
        loop {
            let py = self.nodes[p].y;
            let pn = self.nodes[p].next;
            let pny = self.nodes[pn].y;
            if hy <= py && hy >= pny && pny != py {
                let px = self.nodes[p].x;
                let pnx = self.nodes[pn].x;
                let x = px + (hy - py) * (pnx - px) / (pny - py);
                if x <= hx && x > qx {
                    qx = x;
                    if x == hx {
                        if hy == py {
                            return Some(p);
                        }
                        if hy == pny {
                            return Some(pn);
                        }
                    }
                    m = Some(if px < pnx { p } else { pn });
                }
            }
            p = self.nodes[p].next;
            if p == outer_node {
                break;
            }
        }

        let mut m = m?;

        if hx == qx {
            return Some(self.nodes[m].prev); // hole touches outer segment; pick lower endpoint
        }

        // look for points inside the triangle of hole point, segment
        // intersection and endpoint; if there are no points found, we have a
        // valid connection; otherwise choose the point of the minimum angle
        // with the ray as connection point
        let stop = m;
        let mut tan_min = f64::INFINITY;
        let mx = self.nodes[m].x;
        let my = self.nodes[m].y;

        p = self.nodes[m].next;
        while p != stop {
            let px = self.nodes[p].x;
            let py = self.nodes[p].y;
            if hx >= px
                && px >= mx
                && hx != px
                && point_in_triangle(
                    if hy < my { hx } else { qx },
                    hy,
                    mx,
                    my,
                    if hy < my { qx } else { hx },
                    hy,
                    px,
                    py,
                )
            {
                let tan_cur = (hy - py).abs() / (hx - px); // tangential

                if (tan_cur < tan_min || (tan_cur == tan_min && px > self.nodes[m].x))
                    && self.locally_inside(p, hole)
                {
                    m = p;
                    tan_min = tan_cur;
                }
            }

            p = self.nodes[p].next;
        }

        Some(m)
    }

    /// Interlink polygon nodes in z-order.
    fn index_curve(&mut self, start: usize) {
        let mut p = start;
        loop {
            if self.nodes[p].z == 0 {
                let (x, y) = (self.nodes[p].x, self.nodes[p].y);
                self.nodes[p].z = self.z_order(x, y);
            }
            self.nodes[p].prev_z = Some(self.nodes[p].prev);
            self.nodes[p].next_z = Some(self.nodes[p].next);
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        let pz = self.nodes[p].prev_z.unwrap();
        self.nodes[pz].next_z = None;
        self.nodes[p].prev_z = None;

        self.sort_linked(p);
    }

    /// Simon Tatham's linked list merge sort algorithm
    /// http://www.chiark.greenend.org.uk/~sgtatham/algorithms/listsort.html
    fn sort_linked(&mut self, list: usize) -> usize {
        let mut in_size = 1usize;
        let mut list = list;

        loop {
            let mut p: Option<usize> = Some(list);
            let mut new_list: Option<usize> = None;
            let mut tail: Option<usize> = None;
            let mut num_merges = 0;

            while let Some(p_start) = p {
                num_merges += 1;
                let mut q: Option<usize> = Some(p_start);
                let mut p_size = 0usize;
                for _ in 0..in_size {
                    p_size += 1;
                    q = self.nodes[q.unwrap()].next_z;
                    if q.is_none() {
                        break;
                    }
                }

                let mut q_size = in_size;
                let mut p_cur: Option<usize> = Some(p_start);

                // if there are more unprocessed elements left, carry on
                while p_size > 0 || (q_size > 0 && q.is_some()) {
                    let e: usize;
                    // choose the next merge to work on
                    if p_size == 0 {
                        e = q.unwrap();
                        q = self.nodes[e].next_z;
                        q_size -= 1;
                    } else if q_size == 0 || q.is_none() {
                        e = p_cur.unwrap();
                        p_cur = self.nodes[e].next_z;
                        p_size -= 1;
                    } else if self.nodes[p_cur.unwrap()].z <= self.nodes[q.unwrap()].z {
                        e = p_cur.unwrap();
                        p_cur = self.nodes[e].next_z;
                        p_size -= 1;
                    } else {
                        e = q.unwrap();
                        q = self.nodes[e].next_z;
                        q_size -= 1;
                    }

                    // add the next element to the merged list
                    if let Some(t) = tail {
                        self.nodes[t].next_z = Some(e);
                    } else {
                        new_list = Some(e);
                    }

                    self.nodes[e].prev_z = tail;
                    tail = Some(e);
                }

                p = q;
            }

            self.nodes[tail.unwrap()].next_z = None;

            if num_merges <= 1 {
                return new_list.unwrap();
            }

            list = new_list.unwrap();
            in_size *= 2;
        }
    }

    /// Z-order of a vertex given coords and size of the data bounding box.
    fn z_order(&self, x: f64, y: f64) -> i32 {
        // coords are transformed into non-negative 15-bit integer range
        let mut x = ((x - self.min_x) * self.inv_size) as i32;
        let mut y = ((y - self.min_y) * self.inv_size) as i32;

        x = (x | (x << 8)) & 0x00FF00FF;
        x = (x | (x << 4)) & 0x0F0F0F0F;
        x = (x | (x << 2)) & 0x33333333;
        x = (x | (x << 1)) & 0x55555555;

        y = (y | (y << 8)) & 0x00FF00FF;
        y = (y | (y << 4)) & 0x0F0F0F0F;
        y = (y | (y << 2)) & 0x33333333;
        y = (y | (y << 1)) & 0x55555555;

        x | (y << 1)
    }

    /// Find the leftmost node of a polygon ring.
    fn get_leftmost(&self, start: usize) -> usize {
        let mut p = start;
        let mut leftmost = start;
        loop {
            if self.nodes[p].x < self.nodes[leftmost].x
                || (self.nodes[p].x == self.nodes[leftmost].x
                    && self.nodes[p].y < self.nodes[leftmost].y)
            {
                leftmost = p;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }
        leftmost
    }

    /// Check if a diagonal between two polygon nodes is valid (lies in
    /// polygon interior).
    fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
        let an = self.nodes[a].next;
        let ap = self.nodes[a].prev;
        let bp = self.nodes[b].prev;
        let bn = self.nodes[b].next;

        self.nodes[an].i != self.nodes[b].i
            && self.nodes[ap].i != self.nodes[b].i
            && !self.intersects_polygon(a, b)
            && ((self.locally_inside(a, b)
                && self.locally_inside(b, a)
                && self.middle_inside(a, b)
                && (self.area(ap, a, bp) != 0.0 || self.area(a, bp, b) != 0.0))
                || (self.equals(a, b)
                    && self.area(ap, a, an) > 0.0
                    && self.area(bp, b, bn) > 0.0))
    }

    /// Signed area of a triangle.
    fn area(&self, p: usize, q: usize, r: usize) -> f64 {
        (self.nodes[q].y - self.nodes[p].y) * (self.nodes[r].x - self.nodes[q].x)
            - (self.nodes[q].x - self.nodes[p].x) * (self.nodes[r].y - self.nodes[q].y)
    }

    /// Check if two points are equal.
    fn equals(&self, p1: usize, p2: usize) -> bool {
        self.nodes[p1].x == self.nodes[p2].x && self.nodes[p1].y == self.nodes[p2].y
    }

    /// Check if two segments intersect.
    fn intersects(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
        if (self.equals(p1, q1) && self.equals(p2, q2))
            || (self.equals(p1, q2) && self.equals(p2, q1))
        {
            return true;
        }
        (self.area(p1, q1, p2) > 0.0) != (self.area(p1, q1, q2) > 0.0)
            && (self.area(p2, q2, p1) > 0.0) != (self.area(p2, q2, q1) > 0.0)
    }

    /// Check if a polygon diagonal intersects any polygon segments.
    fn intersects_polygon(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        loop {
            let pn = self.nodes[p].next;
            if self.nodes[p].i != self.nodes[a].i
                && self.nodes[pn].i != self.nodes[a].i
                && self.nodes[p].i != self.nodes[b].i
                && self.nodes[pn].i != self.nodes[b].i
                && self.intersects(p, pn, a, b)
            {
                return true;
            }
            p = self.nodes[p].next;
            if p == a {
                break;
            }
        }
        false
    }

    /// Check if a polygon diagonal is locally inside the polygon.
    fn locally_inside(&self, a: usize, b: usize) -> bool {
        let ap = self.nodes[a].prev;
        let an = self.nodes[a].next;
        if self.area(ap, a, an) < 0.0 {
            self.area(a, b, an) >= 0.0 && self.area(a, ap, b) >= 0.0
        } else {
            self.area(a, b, ap) < 0.0 || self.area(a, an, b) < 0.0
        }
    }

    /// Check if the middle vertex of a polygon diagonal is inside the polygon.
    fn middle_inside(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        let mut inside = false;
        let px = (self.nodes[a].x + self.nodes[b].x) / 2.0;
        let py = (self.nodes[a].y + self.nodes[b].y) / 2.0;
        loop {
            let y1 = self.nodes[p].y;
            let pn = self.nodes[p].next;
            let y2 = self.nodes[pn].y;
            if ((y1 > py) != (y2 > py))
                && y2 != y1
                && (px
                    < (self.nodes[pn].x - self.nodes[p].x) * (py - y1) / (y2 - y1)
                        + self.nodes[p].x)
            {
                inside = !inside;
            }
            p = self.nodes[p].next;
            if p == a {
                break;
            }
        }
        inside
    }

    /// Link two polygon vertices with a bridge; if the vertices belong to the
    /// same polygon, it creates a new polygon.
    fn split_polygon(&mut self, a: usize, b: usize) -> usize {
        let (ai, ax, ay) = (self.nodes[a].i, self.nodes[a].x, self.nodes[a].y);
        let (bi, bx, by) = (self.nodes[b].i, self.nodes[b].x, self.nodes[b].y);
        let a2 = self.new_node(ai, ax, ay);
        let b2 = self.new_node(bi, bx, by);
        let an = self.nodes[a].next;
        let bp = self.nodes[b].prev;

        self.nodes[a].next = b;
        self.nodes[b].prev = a;

        self.nodes[a2].next = an;
        self.nodes[an].prev = a2;

        self.nodes[b2].next = a2;
        self.nodes[a2].prev = b2;

        self.nodes[bp].next = b2;
        self.nodes[b2].prev = bp;

        b2
    }

    /// Create a node and optionally link it with previous one (in a circular
    /// doubly linked list).
    fn insert_node(&mut self, i: usize, pt: [f64; 2], last: Option<usize>) -> usize {
        let p = self.new_node(i as Index, pt[0], pt[1]);

        if let Some(l) = last {
            let ln = self.nodes[l].next;
            self.nodes[p].next = ln;
            self.nodes[p].prev = l;
            self.nodes[ln].prev = p;
            self.nodes[l].next = p;
        }
        p
    }

    fn new_node(&mut self, i: Index, x: f64, y: f64) -> usize {
        let id = self.nodes.len();
        self.nodes.push(Node::new(i, x, y, id));
        id
    }

    fn remove_node(&mut self, p: usize) {
        let next = self.nodes[p].next;
        let prev = self.nodes[p].prev;
        self.nodes[next].prev = prev;
        self.nodes[prev].next = next;

        if let Some(pz) = self.nodes[p].prev_z {
            self.nodes[pz].next_z = self.nodes[p].next_z;
        }
        if let Some(nz) = self.nodes[p].next_z {
            self.nodes[nz].prev_z = self.nodes[p].prev_z;
        }
    }
}

/// Check if a point lies within a convex triangle.
fn point_in_triangle(
    ax: f64,
    ay: f64,
    bx: f64,
    by: f64,
    cx: f64,
    cy: f64,
    px: f64,
    py: f64,
) -> bool {
    (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0.0
        && (ax - px) * (by - py) - (bx - px) * (ay - py) >= 0.0
        && (bx - px) * (cy - py) - (cx - px) * (by - py) >= 0.0
}

/// Triangulate the given polygon (list of rings: outer ring first, then
/// holes). Returns flattened vertex indices forming triangles.
pub fn earcut(points: &[Vec<[f64; 2]>]) -> Vec<Index> {
    let mut e = Earcut::new();
    e.run(points);
    e.indices
}

display.content:
//! Polygon triangulation library: a faithful Rust port of the mapbox `earcut`
//! algorithm (ear clipping with z-order hashing for large inputs), implemented
//! from scratch using only `std`.
//!
//! Polygons are `&[Vec<[f64; 2]>]` — a list of rings, the first being the
//! outer ring and the rest holes. The result is a list of vertex indices
//! (flattened across all rings) forming triangles.

pub type Index = u32;

/// A vertex of the polygon stored in a doubly linked list (plus an optional
/// second linked list used for z-order hashing).
struct Node {
    i: Index,
    x: f64,
    y: f64,
    prev: usize,
    next: usize,
    z: i32,
    prev_z: Option<usize>,
    next_z: Option<usize>,
    steiner: bool,
}

impl Node {
    fn new(i: Index, x: f64, y: f64, id: usize) -> Self {
        Node {
            i,
            x,
            y,
            prev: id,
            next: id,
            z: 0,
            prev_z: None,
            next_z: None,
            steiner: false,
        }
    }
}

pub struct Earcut {
    nodes: Vec<Node>,
    pub indices: Vec<Index>,
    vertices: usize,
    hashing: bool,
    min_x: f64,
    max_x: f64,
    min_y: f64,
    max_y: f64,
    inv_size: f64,
}

impl Default for Earcut {
    fn default() -> Self {
        Self::new()
    }
}

impl Earcut {
    pub fn new() -> Self {
        Earcut {
            nodes: Vec::new(),
            indices: Vec::new(),
            vertices: 0,
            hashing: false,
            min_x: 0.0,
            max_x: 0.0,
            min_y: 0.0,
            max_y: 0.0,
            inv_size: 0.0,
        }
    }

    pub fn run(&mut self, points: &[Vec<[f64; 2]>]) {
        // reset
        self.indices.clear();
        self.vertices = 0;

        if points.is_empty() {
            return;
        }

        let mut threshold: i64 = 80;
        let mut i = 0;
        while threshold >= 0 && i < points.len() {
            threshold -= points[i].len() as i64;
            i += 1;
        }

        // outer node
        let outer_node = match self.linked_list(&points[0], true) {
            Some(n) => n,
            None => return,
        };
        if self.nodes[outer_node].prev == self.nodes[outer_node].next {
            return;
        }

        let mut outer_node = outer_node;
        if points.len() > 1 {
            outer_node = self.eliminate_holes(points, outer_node);
        }

        // if the shape is not too simple, we'll use z-order curve hash later;
        // calculate polygon bbox
        self.hashing = threshold < 0;
        if self.hashing {
            let mut p = self.nodes[outer_node].next;
            self.min_x = self.nodes[outer_node].x;
            self.max_x = self.nodes[outer_node].x;
            self.min_y = self.nodes[outer_node].y;
            self.max_y = self.nodes[outer_node].y;
            loop {
                let x = self.nodes[p].x;
                let y = self.nodes[p].y;
                if x < self.min_x {
                    self.min_x = x;
                }
                if y < self.min_y {
                    self.min_y = y;
                }
                if x > self.max_x {
                    self.max_x = x;
                }
                if y > self.max_y {
                    self.max_y = y;
                }
                p = self.nodes[p].next;
                if p == outer_node {
                    break;
                }
            }

            // min_x, min_y and inv_size are later used to transform coords
            // into integers for z-order calculation
            self.inv_size = (self.max_x - self.min_x).max(self.max_y - self.min_y);
            self.inv_size = if self.inv_size != 0.0 {
                32767.0 / self.inv_size
            } else {
                0.0
            };
        }

        self.earcut_linked(outer_node, 0);
    }

    /// Create a circular doubly linked list from polygon points in the
    /// specified winding order.
    fn linked_list(&mut self, points: &[[f64; 2]], clockwise: bool) -> Option<usize> {
        let mut sum = 0.0f64;
        let len = points.len();
        let mut last: Option<usize> = None;

        // calculate original winding order of a polygon ring
        let mut i = 0;
        let mut j = if len > 0 { len - 1 } else { 0 };
        while i < len {
            let p1 = points[i];
            let p2 = points[j];
            sum += (p2[0] - p1[0]) * (p1[1] + p2[1]);
            j = i;
            i += 1;
        }

        // link points into circular doubly-linked list in the specified
        // winding order
        if clockwise == (sum > 0.0) {
            for i in 0..len {
                last = Some(self.insert_node(self.vertices + i, points[i], last));
            }
        } else {
            let mut i = len;
            while i > 0 {
                i -= 1;
                last = Some(self.insert_node(self.vertices + i, points[i], last));
            }
        }

        if let Some(l) = last {
            let next = self.nodes[l].next;
            if self.equals(l, next) {
                self.remove_node(l);
                last = Some(next);
            }
        }

        self.vertices += len;
        last
    }

    /// Eliminate colinear or duplicate points.
    fn filter_points(&mut self, start: usize, end: Option<usize>) -> usize {
        let mut end = end.unwrap_or(start);
        let mut p = start;
        loop {
            let mut again = false;
            let p_next = self.nodes[p].next;
            let p_prev = self.nodes[p].prev;

            if !self.nodes[p].steiner
                && (self.equals(p, p_next) || self.area(p_prev, p, p_next) == 0.0)
            {
                self.remove_node(p);
                p = p_prev;
                end = p_prev;

                if p == self.nodes[p].next {
                    break;
                }
                again = true;
            } else {
                p = p_next;
            }

            if !(again || p != end) {
                break;
            }
        }
        end
    }

    /// Main ear slicing loop which triangulates a polygon (given as a linked
    /// list).
    fn earcut_linked(&mut self, ear: usize, pass: i32) {
        let mut ear = ear;

        // interlink polygon nodes in z-order
        if pass == 0 && self.hashing {
            self.index_curve(ear);
        }

        let mut stop = ear;

        // iterate through ears, slicing them one by one
        while self.nodes[ear].prev != self.nodes[ear].next {
            let prev = self.nodes[ear].prev;
            let next = self.nodes[ear].next;

            let is_ear = if self.hashing {
                self.is_ear_hashed(ear)
            } else {
                self.is_ear(ear)
            };

            if is_ear {
                // cut off the triangle
                self.indices.push(self.nodes[prev].i);
                self.indices.push(self.nodes[ear].i);
                self.indices.push(self.nodes[next].i);

                self.remove_node(ear);

                // skipping the next vertex leads to less sliver triangles
                ear = self.nodes[next].next;
                stop = ear;

                continue;
            }

            ear = next;

            // if we looped through the whole remaining polygon and can't find
            // any more ears
            if ear == stop {
                if pass == 0 {
                    // try filtering points and slicing again
                    let e = self.filter_points(ear, None);
                    self.earcut_linked(e, 1);
                } else if pass == 1 {
                    // if this didn't work, try curing all small
                    // self-intersections locally
                    let e = self.filter_points(ear, None);
                    let e = self.cure_local_intersections(e);
                    self.earcut_linked(e, 2);
                } else if pass == 2 {
                    // as a last resort, try splitting the remaining polygon
                    // into two
                    self.split_earcut(ear);
                }
                break;
            }
        }
    }

    /// Check whether a polygon node forms a valid ear with adjacent nodes.
    fn is_ear(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);

        // now make sure we don't have other points inside the potential ear
        let mut p = self.nodes[self.nodes[ear].next].next;

        while p != self.nodes[ear].prev {
            if point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[p].x, self.nodes[p].y)
                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].next;
        }

        true
    }

    fn is_ear_hashed(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);

        // triangle bbox; min & max are calculated like this for speed
        let min_tx = ax.min(bx).min(cx);
        let min_ty = ay.min(by).min(cy);
        let max_tx = ax.max(bx).max(cx);
        let max_ty = ay.max(by).max(cy);

        // z-order range for the current triangle bbox
        let min_z = self.z_order(min_tx, min_ty);
        let max_z = self.z_order(max_tx, max_ty);

        // first look for points inside the triangle in increasing z-order
        let mut p = self.nodes[ear].next_z;
        while let Some(pi) = p {
            if self.nodes[pi].z > max_z {
                break;
            }
            if pi != self.nodes[ear].prev
                && pi != self.nodes[ear].next
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[pi].x, self.nodes[pi].y)
                && self.area(self.nodes[pi].prev, pi, self.nodes[pi].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[pi].next_z;
        }

        // then look for points in decreasing z-order
        p = self.nodes[ear].prev_z;
        while let Some(pi) = p {
            if self.nodes[pi].z < min_z {
                break;
            }
            if pi != self.nodes[ear].prev
                && pi != self.nodes[ear].next
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[pi].x, self.nodes[pi].y)
                && self.area(self.nodes[pi].prev, pi, self.nodes[pi].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[pi].prev_z;
        }

        true
    }

    /// Go through all polygon nodes and cure small local self-intersections.
    fn cure_local_intersections(&mut self, start: usize) -> usize {
        let mut start = start;
        let mut p = start;
        loop {
            let a = self.nodes[p].prev;
            let b = self.nodes[self.nodes[p].next].next;

            // a self-intersection where edge (v[i-1],v[i]) intersects
            // (v[i+1],v[i+2])
            if !self.equals(a, b)
                && self.intersects(a, p, self.nodes[p].next, b)
                && self.locally_inside(a, b)
                && self.locally_inside(b, a)
            {
                self.indices.push(self.nodes[a].i);
                self.indices.push(self.nodes[p].i);
                self.indices.push(self.nodes[b].i);

                // remove two nodes involved
                let p_next = self.nodes[p].next;
                self.remove_node(p);
                self.remove_node(p_next);

                p = b;
                start = b;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        self.filter_points(p, None)
    }

    /// Try splitting polygon into two and triangulate them independently.
    fn split_earcut(&mut self, start: usize) {
        // look for a valid diagonal that divides the polygon into two
        let mut a = start;
        loop {
            let mut b = self.nodes[self.nodes[a].next].next;
            while b != self.nodes[a].prev {
                if self.nodes[a].i != self.nodes[b].i && self.is_valid_diagonal(a, b) {
                    // split the polygon in two by the diagonal
                    let c = self.split_polygon(a, b);

                    // filter colinear points around the cuts
                    let a_next = self.nodes[a].next;
                    let a = self.filter_points(a, Some(a_next));
                    let c_next = self.nodes[c].next;
                    let c = self.filter_points(c, Some(c_next));

                    // run earcut on each half
                    self.earcut_linked(a, 0);
                    self.earcut_linked(c, 0);
                    return;
                }
                b = self.nodes[b].next;
            }
            a = self.nodes[a].next;
            if a == start {
                break;
            }
        }
    }

    /// Link every hole into the outer loop, producing a single-ring polygon
    /// without holes.
    fn eliminate_holes(&mut self, points: &[Vec<[f64; 2]>], mut outer_node: usize) -> usize {
        let len = points.len();

        let mut queue = Vec::new();
        for i in 1..len {
            if let Some(list) = self.linked_list(&points[i], false) {
                if list == self.nodes[list].next {
                    self.nodes[list].steiner = true;
                }
                queue.push(self.get_leftmost(list));
            }
        }
        queue.sort_by(|&a, &b| {
            let (xa, xb) = (self.nodes[a].x, self.nodes[b].x);
            if xa < xb {
                std::cmp::Ordering::Less
            } else if xb < xa {
                std::cmp::Ordering::Greater
            } else {
                std::cmp::Ordering::Equal
            }
        });

        // process holes from left to right
        for q in queue {
            outer_node = self.eliminate_hole(q, outer_node);
        }

        outer_node
    }

    /// Find a bridge between vertices that connects hole with an outer ring
    /// and link it.
    fn eliminate_hole(&mut self, hole: usize, outer_node: usize) -> usize {
        let bridge = match self.find_hole_bridge(hole, outer_node) {
            Some(b) => b,
            None => return outer_node,
        };

        let bridge_reverse = self.split_polygon(bridge, hole);

        // filter collinear points around the cuts
        let br_next = self.nodes[bridge_reverse].next;
        self.filter_points(bridge_reverse, Some(br_next));

        // Check if input node was removed by the filtering
        let b_next = self.nodes[bridge].next;
        self.filter_points(bridge, Some(b_next))
    }

    /// David Eberly's algorithm for finding a bridge between hole and outer
    /// polygon.
    fn find_hole_bridge(&self, hole: usize, outer_node: usize) -> Option<usize> {
        let mut p = outer_node;
        let hx = self.nodes[hole].x;
        let hy = self.nodes[hole].y;
        let mut qx = f64::NEG_INFINITY;
        let mut m: Option<usize> = None;

        // find a segment intersected by a ray from the hole's leftmost point
        // to the left; segment's endpoint with lesser x will be potential
        // connection point
        loop {
            let py = self.nodes[p].y;
            let pn = self.nodes[p].next;
            let pny = self.nodes[pn].y;
            if hy <= py && hy >= pny && pny != py {
                let px = self.nodes[p].x;
                let pnx = self.nodes[pn].x;
                let x = px + (hy - py) * (pnx - px) / (pny - py);
                if x <= hx && x > qx {
                    qx = x;
                    if x == hx {
                        if hy == py {
                            return Some(p);
                        }
                        if hy == pny {
                            return Some(pn);
                        }
                    }
                    m = Some(if px < pnx { p } else { pn });
                }
            }
            p = self.nodes[p].next;
            if p == outer_node {
                break;
            }
        }

        let mut m = m?;

        if hx == qx {
            return Some(self.nodes[m].prev); // hole touches outer segment; pick lower endpoint
        }

        // look for points inside the triangle of hole point, segment
        // intersection and endpoint; if there are no points found, we have a
        // valid connection; otherwise choose the point of the minimum angle
        // with the ray as connection point
        let stop = m;
        let mut tan_min = f64::INFINITY;
        let mx = self.nodes[m].x;
        let my = self.nodes[m].y;

        p = self.nodes[m].next;
        while p != stop {
            let px = self.nodes[p].x;
            let py = self.nodes[p].y;
            if hx >= px
                && px >= mx
                && hx != px
                && point_in_triangle(
                    if hy < my { hx } else { qx },
                    hy,
                    mx,
                    my,
                    if hy < my { qx } else { hx },
                    hy,
                    px,
                    py,
                )
            {
                let tan_cur = (hy - py).abs() / (hx - px); // tangential

                if (tan_cur < tan_min || (tan_cur == tan_min && px > self.nodes[m].x))
                    && self.locally_inside(p, hole)
                {
                    m = p;
                    tan_min = tan_cur;
                }
            }

            p = self.nodes[p].next;
        }

        Some(m)
    }

    /// Interlink polygon nodes in z-order.
    fn index_curve(&mut self, start: usize) {
        let mut p = start;
        loop {
            if self.nodes[p].z == 0 {
                let (x, y) = (self.nodes[p].x, self.nodes[p].y);
                self.nodes[p].z = self.z_order(x, y);
            }
            self.nodes[p].prev_z = Some(self.nodes[p].prev);
            self.nodes[p].next_z = Some(self.nodes[p].next);
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        let pz = self.nodes[p].prev_z.unwrap();
        self.nodes[pz].next_z = None;
        self.nodes[p].prev_z = None;

        self.sort_linked(p);
    }

    /// Simon Tatham's linked list merge sort algorithm
    /// http://www.chiark.greenend.org.uk/~sgtatham/algorithms/listsort.html
    fn sort_linked(&mut self, list: usize) -> usize {
        let mut in_size = 1usize;
        let mut list = list;

        loop {
            let mut p: Option<usize> = Some(list);
            let mut new_list: Option<usize> = None;
            let mut tail: Option<usize> = None;
            let mut num_merges = 0;

            while let Some(p_start) = p {
                num_merges += 1;
                let mut q: Option<usize> = Some(p_start);
                let mut p_size = 0usize;
                for _ in 0..in_size {
                    p_size += 1;
                    q = self.nodes[q.unwrap()].next_z;
                    if q.is_none() {
                        break;
                    }
                }

                let mut q_size = in_size;
                let mut p_cur: Option<usize> = Some(p_start);

                // if there are more unprocessed elements left, carry on
                while p_size > 0 || (q_size > 0 && q.is_some()) {
                    let e: usize;
                    // choose the next merge to work on
                    if p_size == 0 {
                        e = q.unwrap();
                        q = self.nodes[e].next_z;
                        q_size -= 1;
                    } else if q_size == 0 || q.is_none() {
                        e = p_cur.unwrap();
                        p_cur = self.nodes[e].next_z;
                        p_size -= 1;
                    } else if self.nodes[p_cur.unwrap()].z <= self.nodes[q.unwrap()].z {
                        e = p_cur.unwrap();
                        p_cur = self.nodes[e].next_z;
                        p_size -= 1;
                    } else {
                        e = q.unwrap();
                        q = self.nodes[e].next_z;
                        q_size -= 1;
                    }

                    // add the next element to the merged list
                    if let Some(t) = tail {
                        self.nodes[t].next_z = Some(e);
                    } else {
                        new_list = Some(e);
                    }

                    self.nodes[e].prev_z = tail;
                    tail = Some(e);
                }

                p = q;
            }

            self.nodes[tail.unwrap()].next_z = None;

            if num_merges <= 1 {
                return new_list.unwrap();
            }

            list = new_list.unwrap();
            in_size *= 2;
        }
    }

    /// Z-order of a vertex given coords and size of the data bounding box.
    fn z_order(&self, x: f64, y: f64) -> i32 {
        // coords are transformed into non-negative 15-bit integer range
        let mut x = ((x - self.min_x) * self.inv_size) as i32;
        let mut y = ((y - self.min_y) * self.inv_size) as i32;

        x = (x | (x << 8)) & 0x00FF00FF;
        x = (x | (x << 4)) & 0x0F0F0F0F;
        x = (x | (x << 2)) & 0x33333333;
        x = (x | (x << 1)) & 0x55555555;

        y = (y | (y << 8)) & 0x00FF00FF;
        y = (y | (y << 4)) & 0x0F0F0F0F;
        y = (y | (y << 2)) & 0x33333333;
        y = (y | (y << 1)) & 0x55555555;

        x | (y << 1)
    }

    /// Find the leftmost node of a polygon ring.
    fn get_leftmost(&self, start: usize) -> usize {
        let mut p = start;
        let mut leftmost = start;
        loop {
            if self.nodes[p].x < self.nodes[leftmost].x
                || (self.nodes[p].x == self.nodes[leftmost].x
                    && self.nodes[p].y < self.nodes[leftmost].y)
            {
                leftmost = p;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }
        leftmost
    }

    /// Check if a diagonal between two polygon nodes is valid (lies in
    /// polygon interior).
    fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
        let an = self.nodes[a].next;
        let ap = self.nodes[a].prev;
        let bp = self.nodes[b].prev;
        let bn = self.nodes[b].next;

        self.nodes[an].i != self.nodes[b].i
            && self.nodes[ap].i != self.nodes[b].i
            && !self.intersects_polygon(a, b)
            && ((self.locally_inside(a, b)
                && self.locally_inside(b, a)
                && self.middle_inside(a, b)
                && (self.area(ap, a, bp) != 0.0 || self.area(a, bp, b) != 0.0))
                || (self.equals(a, b)
                    && self.area(ap, a, an) > 0.0
                    && self.area(bp, b, bn) > 0.0))
    }

    /// Signed area of a triangle.
    fn area(&self, p: usize, q: usize, r: usize) -> f64 {
        (self.nodes[q].y - self.nodes[p].y) * (self.nodes[r].x - self.nodes[q].x)
            - (self.nodes[q].x - self.nodes[p].x) * (self.nodes[r].y - self.nodes[q].y)
    }

    /// Check if two points are equal.
    fn equals(&self, p1: usize, p2: usize) -> bool {
        self.nodes[p1].x == self.nodes[p2].x && self.nodes[p1].y == self.nodes[p2].y
    }

    /// Check if two segments intersect.
    fn intersects(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
        if (self.equals(p1, q1) && self.equals(p2, q2))
            || (self.equals(p1, q2) && self.equals(p2, q1))
        {
            return true;
        }
        (self.area(p1, q1, p2) > 0.0) != (self.area(p1, q1, q2) > 0.0)
            && (self.area(p2, q2, p1) > 0.0) != (self.area(p2, q2, q1) > 0.0)
    }

    /// Check if a polygon diagonal intersects any polygon segments.
    fn intersects_polygon(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        loop {
            let pn = self.nodes[p].next;
            if self.nodes[p].i != self.nodes[a].i
                && self.nodes[pn].i != self.nodes[a].i
                && self.nodes[p].i != self.nodes[b].i
                && self.nodes[pn].i != self.nodes[b].i
                && self.intersects(p, pn, a, b)
            {
                return true;
            }
            p = self.nodes[p].next;
            if p == a {
                break;
            }
        }
        false
    }

    /// Check if a polygon diagonal is locally inside the polygon.
    fn locally_inside(&self, a: usize, b: usize) -> bool {
        let ap = self.nodes[a].prev;
        let an = self.nodes[a].next;
        if self.area(ap, a, an) < 0.0 {
            self.area(a, b, an) >= 0.0 && self.area(a, ap, b) >= 0.0
        } else {
            self.area(a, b, ap) < 0.0 || self.area(a, an, b) < 0.0
        }
    }

    /// Check if the middle vertex of a polygon diagonal is inside the polygon.
    fn middle_inside(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        let mut inside = false;
        let px = (self.nodes[a].x + self.nodes[b].x) / 2.0;
        let py = (self.nodes[a].y + self.nodes[b].y) / 2.0;
        loop {
            let y1 = self.nodes[p].y;
            let pn = self.nodes[p].next;
            let y2 = self.nodes[pn].y;
            if ((y1 > py) != (y2 > py))
                && y2 != y1
                && (px
                    < (self.nodes[pn].x - self.nodes[p].x) * (py - y1) / (y2 - y1)
                        + self.nodes[p].x)
            {
                inside = !inside;
            }
            p = self.nodes[p].next;
            if p == a {
                break;
            }
        }
        inside
    }

    /// Link two polygon vertices with a bridge; if the vertices belong to the
    /// same polygon, it creates a new polygon.
    fn split_polygon(&mut self, a: usize, b: usize) -> usize {
        let (ai, ax, ay) = (self.nodes[a].i, self.nodes[a].x, self.nodes[a].y);
        let (bi, bx, by) = (self.nodes[b].i, self.nodes[b].x, self.nodes[b].y);
        let a2 = self.new_node(ai, ax, ay);
        let b2 = self.new_node(bi, bx, by);
        let an = self.nodes[a].next;
        let bp = self.nodes[b].prev;

        self.nodes[a].next = b;
        self.nodes[b].prev = a;

        self.nodes[a2].next = an;
        self.nodes[an].prev = a2;

        self.nodes[b2].next = a2;
        self.nodes[a2].prev = b2;

        self.nodes[bp].next = b2;
        self.nodes[b2].prev = bp;

        b2
    }

    /// Create a node and optionally link it with previous one (in a circular
    /// doubly linked list).
    fn insert_node(&mut self, i: usize, pt: [f64; 2], last: Option<usize>) -> usize {
        let p = self.new_node(i as Index, pt[0], pt[1]);

        if let Some(l) = last {
            let ln = self.nodes[l].next;
            self.nodes[p].next = ln;
            self.nodes[p].prev = l;
            self.nodes[ln].prev = p;
            self.nodes[l].next = p;
        }
        p
    }

    fn new_node(&mut self, i: Index, x: f64, y: f64) -> usize {
        let id = self.nodes.len();
        self.nodes.push(Node::new(i, x, y, id));
        id
    }

    fn remove_node(&mut self, p: usize) {
        let next = self.nodes[p].next;
        let prev = self.nodes[p].prev;
        self.nodes[next].prev = prev;
        self.nodes[prev].next = next;

        if let Some(pz) = self.nodes[p].prev_z {
            self.nodes[pz].next_z = self.nodes[p].next_z;
        }
        if let Some(nz) = self.nodes[p].next_z {
            self.nodes[nz].prev_z = self.nodes[p].prev_z;
        }
    }
}

/// Check if a point lies within a convex triangle.
fn point_in_triangle(
    ax: f64,
    ay: f64,
    bx: f64,
    by: f64,
    cx: f64,
    cy: f64,
    px: f64,
    py: f64,
) -> bool {
    (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0.0
        && (ax - px) * (by - py) - (bx - px) * (ay - py) >= 0.0
        && (bx - px) * (cy - py) - (cx - px) * (by - py) >= 0.0
}

/// Triangulate the given polygon (list of rings: outer ring first, then
/// holes). Returns flattened vertex indices forming triangles.
pub fn earcut(points: &[Vec<[f64; 2]>]) -> Vec<Index> {
    let mut e = Earcut::new();
    e.run(points);
    e.indices
}

