mod earcut;

use std::env;
use std::io::Write;

/// Equivalent of C's `atoi`: skips leading whitespace, accepts an optional
/// sign, then parses consecutive digits; returns 0 if none.
fn atoi(s: &str) -> i32 {
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() && (bytes[i] as char).is_whitespace() {
        i += 1;
    }
    let mut sign: i64 = 1;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        if bytes[i] == b'-' {
            sign = -1;
        }
        i += 1;
    }
    let mut value: i64 = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        value = value * 10 + (bytes[i] - b'0') as i64;
        i += 1;
    }
    (sign * value) as i32
}

fn main() {
    let args: Vec<String> = env::args().collect();

    let mut n: i32 = 2;
    if args.len() > 1 {
        n = atoi(&args[1]);
    }

    let nf = n as f64;

    let mut polygon: Vec<Vec<[f64; 2]>> = Vec::new();
    polygon.push(vec![[0.0, 0.0], [nf, 0.0], [nf, nf], [0.0, nf]]);

    if n > 1 {
        polygon.push(vec![
            [0.25 * nf, 0.25 * nf],
            [0.75 * nf, 0.25 * nf],
            [0.75 * nf, 0.75 * nf],
            [0.25 * nf, 0.75 * nf],
        ]);
    }

    let indices = earcut::earcut(&polygon);

    let mut out = String::new();
    for idx in indices {
        out.push_str(&idx.to_string());
        out.push(' ');
    }
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    let _ = lock.write_all(out.as_bytes());
    let _ = lock.flush();
}

